provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "/aws/route53/example.com"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  policy_document = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "route53.amazonaws.com"
        },
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ],
        Resource = "arn:aws:logs:*:*:log-group:/aws/route53/example.com"
      }
    ]
  })
  policy_name = "route53-query-logging-policy"
}

resource "aws_route53_zone" "example_com" {
  name = "example.com"
}

resource "aws_cloudwatch_log_stream" "aws_route53_example_com_stream" {
  log_group_name = aws_cloudwatch_log_group.aws_route53_example_com.arn
  name           = "example.com-stream"
}

resource "aws_route53_query_log" "example_com_query_log" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
