```hcl
provider "aws" {
  region = "us-east-1"
}

variable "db_name" {
  description = "Name of the database"
  default     = "internal"
}

variable "db_type" {
  description = "Type of the database (e.g., mysql)"
  default     = "mysql"
}

variable "db_version" {
  description = "Version of the database"
  default     = "8.0.23"
}

variable "db_instance_class" {
  description = "Class of the database instance"
  default     = "t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the database instance"
  default     = 20
}

resource "aws_vpc" "vpc_main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_main" {
  vpc_id          = aws_vpc.vpc_main.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "sg_main" {
  vpc_id = aws_vpc.vpc_main.id
  description = "Allow inbound HTTP and HTTPS traffic"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_instance" "db_internal" {
  engine         = var.db_type
  engine_version = var.db_version
  instance_class = var.db_instance_class
  allocated_storage = var.db_allocated_storage
  vpc_security_group_ids = [aws_security_group.sg_main.id]
  db_subnet_group_name = "main"
  publicly_accessible = false
  tags = {
    Name = var.db_name
  }
}

resource "aws_rds_instance" "db_public" {
  engine         = var.db_type
  engine_version = var.db_version
  instance_class = var.db_instance_class
  allocated_storage = var.db_allocated_storage
  vpc_security_group_ids = [aws_security_group.sg_main.id]
  db_subnet_group_name = "main"
  publicly_accessible = true
  tags = {
    Name = var.db_name
  }
}

resource "aws_route_table" "rtb_private" {
  vpc_id = aws_vpc.vpc_main.id
}

resource "aws_route_table" "rtb_public" {
  vpc_id = aws_vpc.vpc_main.id
}

resource "aws_route" "route_private" {
  route_table_id = aws_route_table.rtb_private.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.internet_gateway.id
}

resource "aws_route" "route_public" {
  route_table_id = aws_route_table.rtb_public.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id = aws_nat_gateway.nat_gateway.id
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc_main.id
}

resource "aws_nat_gateway" "nat_gateway" {
  allocation_id = aws_eip.eip.id
  subnet_id      = aws_subnet.subnet_main.id
}

resource "aws_eip" "eip" {
  vpc = true
}

resource "aws_route53_zone" "zone_private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "zone_public" {
  name = "public.example.com"
}

resource "aws_route53_record" "record_private" {
  zone_id = aws_route53_zone.zone_private.id
  name    = var.db_name
  type    = "A"
  ttl     = 300
  records = [aws_rds_instance.db_internal.endpoint]
}

resource "aws_route53_record" "record_public" {
  zone_id = aws_route53_zone.zone_public.id
  name    = var.db_name
  type    = "A"
  ttl     = 300
  records = [aws_rds_instance.db_public.endpoint]
}
```

