variable "eu_central_region" {
  default = "eu-central-1"  # Default region for eu_central environment
}

resource "aws_iam_role" "elastic_beanstalk_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "elastic_beanstalk_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBeanstalkServiceRole"
  role       = aws_iam_role.elastic_beanstalk_role.name
}

resource "aws_route53_zone" "us_west_route53_zone" {
  name = "us-west.example.com"
}

resource "aws_route53_record" "us_west_route53_record" {
  zone_id = aws_route53_zone.us_west_route53_zone.zone_id
  name    = "us-west"
  type    = "A"
  alias {
    evaluate_target_health = true
    name                  = aws_route53_zone.us_west_route53_zone.name_servers[0]
    zone_id               = aws_route53_zone.us_west_route53_zone.zone_id
  }
}

resource "aws_elastic_beanstalk_application" "us_west_app" {
  name        = "us-west-app"
  description = "US West Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "us_west_env" {
  name                = "us-west-env"
  application         = aws_elastic_beanstalk_application.us_west_app.name
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"
  cname_prefix        = "us-west-env"
  tags = {
    Environment = "us-west"
  }
}

resource "aws_route53_zone" "eu_central_route53_zone" {
  name = "eu-central.example.com"
}

resource "aws_route53_record" "eu_central_route53_record" {
  zone_id = aws_route53_zone.eu_central_route53_zone.zone_id
  name    = "eu-central"
  type    = "A"
  alias {
    evaluate_target_health = true
    name                  = aws_route53_zone.eu_central_route53_zone.name_servers[0]
    zone_id               = aws_route53_zone.eu_central_route53_zone.zone_id
  }
}

resource "aws_elastic_beanstalk_application" "eu_central_app" {
  name        = "eu-central-app"
  description = "EU Central Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "eu_central_env" {
  name                = "eu-central-env"
  application         = aws_elastic_beanstalk_application.eu_central_app.name
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"
  cname_prefix        = "eu-central-env"
  tags = {
    Environment = "eu-central"
  }
}
