        "Can you help me book a trip to {Destination} on {TravelDate}",
      ]

      value_elicitation_prompt {
        max_attempts = 2

        message {
          content      = "What date would you like to book the trip to {Destination}?"
          content_type = "PlainText"
        }
      }
    }

    slot {
      name        = "TravelDuration"
      slot_constraint = "Required"
      slot_type         = "AMAZON.DURATION"
      description = "The duration of the trip."

      sample_utterances = [
        "I want to book a trip to {Destination} for {TravelDuration}",
        "Can you help me book a trip to {Destination} for {TravelDuration}",
      ]

      value_elicitation_prompt {
        max_attempts = 2

        message {
          content      = "How long would you like to book the trip to {Destination}?"
          content_type = "PlainText"
        }
      }
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand your request. Please try again."
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content      = "I'm sorry, I can't assist with that."
      content_type = "PlainText"
    }
  }
}
