provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the Lambda function
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "lambda_policy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = "s3:GetObject"
          Effect = "Allow"
          Resource = "arn:aws:s3:::my-bucket/*"
        },
        {
          Action = "logs:CreateLogGroup"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Action = "logs:CreateLogStream"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Action = "logs:PutLogEvents"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
      ]
    })
  }
}

# Create an S3 bucket for storing Lambda function code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "my-lambda-code-bucket"
  acl    = "private"
}

# Upload Lambda function code to the S3 bucket
resource "aws_s3_bucket_object" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "pizza_order_handler.zip"
  source = "path/to/pizza_order_handler.zip"
}

# Create a Lambda function
resource "aws_lambda_function" "pizza_order_handler" {
  function_name = "pizza_order_handler"
  role          = aws_iam_role.lambda_execution_role.arn
  runtime       = "python3.8"
  handler       = "pizza_order_handler.handler"

  code {
    s3_bucket = aws_s3_bucket.lambda_code_bucket.bucket
    s3_key    = aws_s3_bucket_object.lambda_code.key
  }

  environment {
    variables = {
      PIZZA_STORE_URL = "https://example.com/pizza-store"
    }
  }

  timeout = 30
  memory_size = 128
}

# Create an Amazon Lex bot
resource "aws_lex_bot" "pizza_order_bot" {
  name           = "pizza_order_bot"
  child_directed = false
  description     = "Bot to order pizzas on the behalf of a user"
  idle_session_ttl_in_seconds = 600
  locale           = "en-US"
  process_behavior = "BUILD"

  intent {
    intent_name    = "OrderPizza"
    intent_version = "1"
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand you, what would you like to do?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time"
      content_type = "PlainText"
    }
  }

