    name        = "PizzaSize"
    slot_type   = "PizzaSizes"
    description = "Size of the pizza to order"
    slot_constraint = "Required"

    sample_utterances = [
      "I would like a {PizzaSize} pizza",
      "Can you order me a {PizzaSize} pizza?",
    ]

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like to order?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name        = "Quantity"
    slot_type   = "Quantities"
    description = "Number of pizzas to order"
    slot_constraint = "Required"

    sample_utterances = [
      "I would like {Quantity} {PizzaSize} pizzas",
      "Can you order me {Quantity} {PizzaSize} pizzas?",
