provider "aws" {
  region = "us-east-1"
}

# Create a VPC with two subnets and a security group
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "tf-kinesis-firehose-vpc"
  }
}

resource "aws_subnet" "subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "tf-kinesis-firehose-subnet-1"
  }
}

resource "aws_subnet" "subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"

  tags = {
    Name = "tf-kinesis-firehose-subnet-2"
  }
}

resource "aws_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "tf-kinesis-firehose-security-group"
  }
}

# Create an OpenSearch domain with a VPC endpoint
resource "aws_opensearch_domain" "main" {
  domain_name = "tf-kinesis-firehose-os"

  cluster_config {
    instance_count         = 2
    zone_awareness_enabled = true
    instance_type          = "t3.micro"
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  vpc_options {
    security_group_ids = [aws_security_group.main.id]
    subnet_ids         = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
  }

  # Remove the unsupported endpoint_type attribute
}

# Create an IAM role for Firehose to access OpenSearch
resource "aws_iam_role" "firehose_role" {
  name = "tf-kinesis-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "tf-kinesis-firehose-role"
  }
}

# Attach an OpenSearch policy to the Firehose role
resource "aws_iam_role_policy_attachment" "firehose_policy" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseServiceRole"
}

# Create an S3 bucket for Firehose backup
resource "aws_s3_bucket" "firehose_backup" {
  bucket = "tf-kinesis-firehose-backup"

  tags = {
    Name = "tf-kinesis-firehose-backup"
  }
}

# Create an IAM role for Firehose to access S3
resource "aws_iam_role" "firehose_s3_role" {
  name = "tf-kinesis-firehose-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "tf-kinesis-firehose-s3-role"
  }
}

# Attach an S3 policy to the Firehose S3 role
resource "aws_iam_role_policy_attachment" "firehose_s3_policy" {
  role       = aws_iam_role.firehose_s3_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseS3DeliveryRole"
}

# Create a Kinesis Firehose delivery stream with OpenSearch destination and VPC
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "tf-kinesis-firehose-os-stream"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = aws_opensearch_domain.main.arn
    role_arn   = aws_iam_role.firehose_role.arn
    index_name = "tf-kinesis-firehose-os-index"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_s3_role.arn
      bucket_arn = aws_s3_bucket.firehose_backup.arn
    }

    vpc_config {
      subnet_ids         = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
      security_group_ids = [aws_security_group.main.id]
      role_arn           = aws_iam_role.firehose_role.arn
    }
  }
}
```

