    prefix  = ""

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 60
      storage_class = "GLACIER"
    }
  }

  lifecycle_rule {
    id      = "noncurrent-version-deletion"
    status = "Enabled"
    prefix  = ""

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}
