provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = "s3-event-notification-topic"
}

resource "aws_iam_policy" "s3_event_notification_policy" {
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "SNS:Publish"
        Resource = aws_sns_topic.s3_event_notification_topic.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:aws:s3:::your-bucket-name"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "your_bucket_name" {
  bucket = "your-bucket-name"

  lifecycle_rule {
    id      = "log-files"
    enabled = true
    prefix  = "*.log"

    expiration {
      days = 30
    }
  }

  notification_configuration {
    topic {
      topic_arn     = aws_sns_topic.s3_event_notification_topic.arn
      events        = ["s3:ObjectCreated:*"]
      filter_suffix = ".log"
    }
  }
}

resource "aws_iam_role" "sns_topic_role" {
  name = "sns_topic_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sns_topic_policy_attachment" {
