```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for SageMaker to assume
resource "aws_iam_role" "sagemaker_assume_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for SageMaker to access S3
resource "aws_iam_policy" "sagemaker_policy" {
  name = "sagemaker-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.kmeans_model.bucket}",
          "${aws_s3_bucket.kmeans_model.arn}/*"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "sagemaker_policy_attachment" {
  role       = aws_iam_role.sagemaker_assume_role.name
  policy_arn = aws_iam_policy.sagemaker_policy.arn
}

# Create an S3 bucket for model artifacts
resource "aws_s3_bucket" "kmeans_model" {
  bucket = "kmeans-model-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name = "KMeans Model Bucket"
  }
}

# Create an S3 object for the KMeans model
resource "aws_s3_bucket_object" "kmeans_model_object" {
  bucket = aws_s3_bucket.kmeans_model.bucket
  key    = "kmeans-model.tar.gz"
  source = "path/to/kmeans-model.tar.gz"

  acl = "private"
}

# Create a random string resource for the bucket name
resource "random_string" "random_suffix" {
  length = 8
  special = false
  upper = false
  lower = true
  number = true
}

# Create a SageMaker model using the KMeans model artifact
resource "aws_sagemaker_model" "kmeans_model" {
  name               = "kmeans-model"
  execution_role_arn = aws_iam_role.sagemaker_assume_role.arn

  container {
    image = "763104351884.dkr.ecr.us-west-2.amazonaws.com/sagemaker-kmeans:latest"
    model_data_url = aws_s3_bucket_object.kmeans_model_object.bucket_arn + "/kmeans-model.tar.gz"
  }
}
```

