provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "us_east_1a" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "us_east_1a"
  }
}

resource "aws_subnet" "us_east_1b" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "us_east_1b"
  }
}

resource "aws_launch_template" "latest_ami" {
  name_prefix = "latest-amazon-linux-2"
  image_id = data.aws_ami.latest_amazon_linux_2.id
  instance_type = "t2.micro"
  disable_api_termination = true
  disable_api_stop = true
  ebs_optimized = true
  key_name = "my-key-pair" # Replace with your key pair name
  security_group_ids = [aws_security_group.default.id] # Removed the unsupported argument
  tags = {
    Name = "latest-amazon-linux-2-launch-template"
  }

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_size = 50
      encrypted = true
    }
  }
}

resource "aws_security_group" "default" {
  name        = "default"
  description = "Default security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "us_east_1a_instance" {
  ami           = aws_launch_template.latest_ami.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.us_east_1a.id
  key_name      = aws_security_group.default.key_name
  security_groups = [aws_security_group.default.id]

  tags = {
    Name = "us_east_1a-instance"
  }
}

resource "aws_instance" "us_east_1b_instance" {
