  bucket = aws_s3_bucket.msk_logs_bucket.id
  target_bucket = aws_s3_bucket.msk_logs_bucket.id
  target_prefix = "logs/"
}

resource "aws_iam_role" "msk_logs_role" {
  name = "msk_logs_role-${random_string.random_suffix.result}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_logs_role_policy_attachment" {
  role       = aws_iam_role.msk_logs_role.id
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKafkaReadOnlyAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster-${random_string.random_suffix.result}"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id]
    security_groups = [aws_security_group.msk_sg.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs_bucket_logging.id
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_delivery_stream.id
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.id
        prefix  = "logs/msk-"
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}

resource "aws_cloudwatch_log_group" "msk_logs_bucket_logging" {
  name = "msk-broker-logs-${random_string.random_suffix.result}"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs_delivery_stream" {
  name        = "msk-logs-delivery-stream-${random_string.random_suffix.result}"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_logs_role.arn
    bucket_arn = aws_s3_bucket.msk_logs_bucket.id
  }

  tags = {
    LogDeliveryEnabled = "true"
  }

  lifecycle {
    ignore_changes = [
      tags["LogDeliveryEnabled"],
    ]
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
  upper = false
  lower = true
  number = true
}
