      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.name
        prefix  = "logs/msk/"
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name        = "my-msk-logs-firehose"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_logs_firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_logs_bucket.arn
  }
}

resource "aws_cloudwatch_log_group" "msk_logs_log_group" {
  name = "my-msk-logs-log-group"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "my-msk-logs-bucket"
}

resource "aws_iam_role" "msk_logs_firehose_role" {
  name               = "msk-logs-firehose-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kms_key" "msk_key" {
  description = "KMS key for MSK encryption"
}
```

