    client_subnets = [aws_subnet.msk_subnet_1.id, aws_subnet.msk_subnet_2.id, aws_subnet.msk_subnet_3.id]
    security_groups = [aws_security_group.msk_sg.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_log_bucket.name
        prefix  = "logs/msk-"
      }
    }
  }
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "msk_broker_logs"
}

resource "aws_s3_bucket" "msk_log_bucket" {
  bucket = "msk-log-bucket-${var.account_id}"
  tags = {
    Name = "MSK Log Bucket"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = "msk-firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_log_bucket.arn

    processing_configuration {
      enabled = true

      processors {
        type = "Lambda"
        parameters {
          parameter_name  = "LambdaArn"
          parameter_value = "${aws_lambda_function.msk_lambda_processor.arn}:$LATEST"
        }
      }
    }
  }
}

resource "aws_iam_role" "msk_firehose_role" {
  name               = "msk-firehose-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_lambda_function" "msk_lambda_processor" {
  filename      = "lambda.zip"
  function_name = "msk-lambda-processor"
  role          = aws_iam_role.msk_firehose_role.arn
  handler       = "exports.handler"
  runtime       = "nodejs20.x"
}
