provider "aws" {
  region = "us-west-2"
}

variable "master_password" {
  description = "Master password for the Redshift cluster"
  type        = string
  default     = "SecurePassword123!"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type         = "dc1.large"

  allow_version_upgrade = true
  apply_immediately   = true
  cluster_parameter_group_name = "default.redshift-1.x"
  cluster_subnet_group_name = "my-redshift-subnet-group"
  cluster_type = "single-node"
  multi_az = false
  automated_snapshot_retention_period = 7
  availability_zone = "us-west-2a"
  cluster_version = "1.0.0"
  database_name = "mydatabase"
  default_iam_role_arn = aws_iam_role.redshift_notification_role.arn
  encrypted = true
  endpoint = aws_redshift_cluster.redshift_cluster.endpoint
  enhanced_vpc_routing = true
  final_snapshot_identifier = "my-final-snapshot"
  iam_roles = [aws_iam_role.redshift_notification_role.arn]
  master_username = "admin"
  number_of_nodes = 1
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]

  logging {
    enable = true
    bucket_name = "my-redshift-logs"
    log_destination_type = "s3"
    log_exports = ["dlq", "information"]
    s3_key_prefix = "redshift/logs/"
  }
}

resource "aws_iam_role" "redshift_notification_role" {
  name = "redshift-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "redshift_notification_policy_attachment" {
  name = "redshift-notification-policy-attachment"

  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRedshiftSNSNotificationAccess"

  roles = [aws_iam_role.redshift_notification_role.name]
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
