    Environment = "Development"
  }
}

resource "aws_iam_role_policy" "autograder_service_role_policy" {
  role   = aws_iam_role.autograder_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:DeleteObject",
        ]
        Resource = [
          "${aws_s3_bucket.autograder_results_bucket.arn}",
          "${aws_s3_bucket.autograder_results_bucket.arn}/*",
        ]
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "*",
        ]
      },
    ]
  })
}

resource "aws_codebuild_project" "autograder_project" {
  name          = "cs-class-autograder-project-${random_string.random_suffix.result}"
  description   = "Autograder for CS Class"
  service_role  = aws_iam_role.autograder_service_role.arn
  build_timeout = 60

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
