    image_pull_credentials_type = "CODEBUILD"
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "cs-class-autograder-logs"
      stream_name = "cs-class-autograder-stream"
    }

    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.autograder_results_bucket.id}/build-log"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.repo_owner}/${var.repo_name}.git"
    git_clone_depth = 1
  }

  tags = {
    Name        = "CS-Class-Autograder-Project"
    Environment = "Development"
  }
}

resource "random_string" "random_suffix" {
