provider "aws" {
  region = "us-east-1"
}

variable "public_dns" {
  default = aws_vpc.video_streaming_vpc.public_dns
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  description = "Allow HTTP and HTTPS traffic"
  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port = 443
    to_port = 443
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "example.com"
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.id
  name = "www"
  type = "A"
  ttl = 300
  records = [var.public_dns]
}

resource "aws_lb" "video_streaming_lb" {
  name = "video-streaming-lb"
  subnets = [aws_subnet.video_streaming_subnet.id]
  security_groups = [aws_security_group.video_streaming_sg.id]
  load_balancer_type = "application"
  enable_cross_zone_load_balancing = true
  tags = {
    Name = "Video Streaming Load Balancer"
  }
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name = "video-streaming-target-group"
  port = 80
  protocol = "HTTP"
  target_type = "instance"
  vpc_id = aws_vpc.video_streaming_vpc.id
  health_check {
    enabled = true
    healthy_threshold = 2
    interval = 30
    matcher = "200"
    path = "/"
    port = 80
    protocol = "HTTP"
    timeout = 10
    unhealthy_threshold = 2
  }
  stickiness {
    type = "lb_cookie"
    cookie_duration = 86400
  }
}

