    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "mysql_db_param_group" {
  family = "mysql8.0"
  name   = "mysql_db_param_group"

  parameter {
    name         = "character_set_server"
    value        = "utf8mb4"
    apply_method = "immediate"
  }

  parameter {
    name         = "collation_server"
    value        = "utf8mb4_unicode_ci"
    apply_method = "immediate"
  }
}

resource "aws_db_instance" "mysql_db_instance" {
  instance_class = "db.t3.micro"
  engine         = "mysql"
  engine_version = "8.0"
  allocated_storage = 20
