  default     = "dev"
}

resource "aws_s3_bucket" "lightsail_distribution_origin_bucket" {
  bucket = "lightsail-distribution-origin-bucket-${var.environment}"
  acl    = "private"

  tags = {
    Environment = var.environment
  }
}

resource "aws_s3_bucket_policy" "lightsail_distribution_origin_bucket_policy" {
  bucket = aws_s3_bucket.lightsail_distribution_origin_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.lightsail_distribution_origin_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "lightsail_distribution" {
  enabled = true

  origin {
    domain_name = aws_s3_bucket.lightsail_distribution_origin_bucket.bucket_domain_name
    origin_id   = aws_s3_bucket.lightsail_distribution_origin_bucket.bucket
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.lightsail_distribution_origin_bucket.bucket
    viewer_protocol_policy = "allow-all"
  }

  logging_config {
    bucket = aws_s3_bucket.lightsail_distribution_origin_bucket.bucket
    include_cookies = false
    prefix = "logs/"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    ssl_support_method = "sni-only"
    acm_certificate_arn = aws_acm_certificate.example.arn
  }
}

resource "aws_acm_certificate" "example" {
  domain_name = "example.com"
  validation_method = "dns"

  subject_alternative_names = [
    "*.example.com"
  ]

  tags = {
    Environment = var.environment
  }
}
```

