}

resource "aws_s3_bucket_policy" "glacier_bucket_policy" {
  bucket = aws_s3_bucket.glacier_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.glacier_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_notification" "glacier_bucket_notification" {
  bucket = aws_s3_bucket.glacier_bucket.bucket

  lambda_function {
    lambda_function_arn = aws_lambda_function.glacier_lambda.function_arn
    events            = ["s3:ObjectCreated:*"]
  }
}

