  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "example_load_balancer" {
  name               = "example-load-balancer"
  internal           = false
  subnets            = aws_subnet.example[*].id
  security_groups     = [aws_security_group.example.id]
  load_balancer_type = "application"

  access_logs {
    bucket = "example-access-logs-bucket"
    enabled = true
    prefix = "load-balancer-logs/"
  }

  connection_logs {
    bucket = "example-connection-logs-bucket"
    enabled = true
    prefix = "load-balancer-connections/"
  }

  timeouts {
    create = "60m"
    delete = "60m"
    update = "60m"
  }
}

resource "aws_lb_target_group" "example_target_group" {
  name        = "example-target-group"
  port         = 80
  protocol     = "HTTP"
  vpc_id       = aws_vpc.example.id
  target_type  = "instance"
  health_check {
    enabled     = true
    healthy_threshold = 2
    interval       = 30
    matcher        = "200"
    path           = "/"
    port           = "traffic-port"
    protocol       = "HTTP"
    timeout        = 10
    unhealthy_threshold = 2
  }
}

resource "aws_lambda_function" "example_lambda_function" {
  function_name = "example-lambda-function"
  role          = aws_iam_role.example.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  code {
    s3_bucket = "example-lambda-code-bucket"
    s3_key    = "lambda-function.zip"
  }

  environment {
    variables = {
      API_URL = "http://${aws_lb.example_load_balancer.dns_name}"
    }
  }

  tags = {
    Name = "example-lambda-function"
  }
}

resource "aws_iam_role" "example" {
