provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  default = "10.1.0.0/16"
}

variable "enable_dns_hostnames" {
  default = true
}

variable "enable_dns_support" {
  default = true
}

variable "enable_network_address_usage_metrics" {
  default = true
}

resource "aws_vpc" "pike" {
  cidr_block                       = var.vpc_cidr_block
  assign_generated_ipv6_cidr_block = true
  enable_dns_hostnames            = var.enable_dns_hostnames
  enable_dns_support              = var.enable_dns_support
  enable_network_address_usage_metrics = var.enable_network_address_usage_metrics
  tags = {
    Name = "pike"
  }
}

resource "aws_egress_only_internet_gateway" "pike" {
  vpc_id = aws_vpc.pike.id

  tags = {
    Name = "pike"
    permissions = "allow-ipv6"
  }
}

resource "aws_security_group" "pike" {
  name        = "pike-egress-only"
  description = "Allow IPv6 outbound traffic from instances in the pike VPC"
  vpc_id      = aws_vpc.pike.id

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol    = "-1"
  }

  egress {
    cidr_blocks = ["::/0"]
    protocol    = "-1"
  }

  tags = {
    Name = "pike-egress-only"
    permissions = "allow-ipv6"
  }
}
